mapper.insert:
/*
  QueryID : com.kdt.mapper.interview.insertApplyInterview
  Description : 클라이언트의 면담 요청을 받아 TB_INTERVIEW에 insert
  작성자 : 김동식
  */
INSERT INTO TB_INTERVIEW (
    ITV_APLCNT_SN,
    ITV_APLY_TTL, ITV_APLY_CN, COHORT_SN, FORM_UUID, ITV_PIC_AUTHRT, ITV_APLY_DT
) VALUES (
             #{itvAplcntSn},
             #{itvAplyTtl}, #{itvAplyCn}, #{cohortSn}, #{formUuid}, #{itvPicAuthrt}, #{itvAplyDt}
         )

mapper.select:
/* QueryID : com.kdt.mapper.interview.getMyInterviewRequests Description : 회사내 모든 기수의 배정되지 않은 면담을 보여준다. (가장 오래된 신청부터) Author: 구서영 Rule: - 대표(2): ITV_PIC_AUTHRT = 2 - 직원(3): ITV_PIC_AUTHRT = 3 - 강사(4): ITV_PIC_AUTHRT = 4 - 공통: COHORT_SN = cohortSn -> 여기 샵 괄호 이런거 쓰면 에러뜸 사용 ㄴㄴ */ SELECT i.ITV_SN, i.COHORT_SN, i.ITV_APLY_TTL, i.ITV_APLY_CN, i.ITV_APLY_DT, i.ITV_PIC_AUTHRT, i.ITV_PIC_SN, i.ITV_APLCNT_SN, i.ITV_PRNMNT_DT, i.ITV_PLC, i.PIC_CAL_SN, i.APLCNT_CAL_SN, '면담요청' AS postType FROM TB_INTERVIEW i JOIN TB_COHORT c ON c.COHORT_SN = i.COHORT_SN WHERE 1=1 AND c.CO_SN = #{coSn}
AND i.COHORT_SN = #{cohortSn}
AND i.ITV_PIC_AUTHRT = #{roleType}
AND i.ITV_PRNMNT_DT IS NULL ORDER BY i.ITV_APLY_DT ASC
